package io.github.mymayankyadav.lemma;
import android.content.*;import android.database.*;import android.net.*;import android.provider.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.io.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;
public class CalendarRaceReproTest {
 static class Rows implements Cursor{final List<Object[]>rows;int index=-1;Rows(List<Object[]>r){rows=r;}public boolean moveToFirst(){index=0;return !rows.isEmpty();}public boolean moveToNext(){return ++index<rows.size();}public long getLong(int i){return((Number)rows.get(index)[i]).longValue();}public int getInt(int i){return((Number)rows.get(index)[i]).intValue();}public String getString(int i){return(String)rows.get(index)[i];}public boolean isNull(int i){return rows.get(index)[i]==null;}public void close(){}}
 static class Provider extends ContentResolver{final List<Long>calendars=Collections.synchronizedList(new ArrayList<>());final Map<Long,ContentValues>events=new ConcurrentHashMap<>();final AtomicLong next=new AtomicLong();final AtomicInteger calendarQueries=new AtomicInteger();final CyclicBarrier barrier=new CyclicBarrier(2);public String getType(Uri u){return null;}public InputStream openInputStream(Uri u){return null;}
 public Cursor query(Uri uri,String[]p,String s,String[]a,String o){if(uri.toString().startsWith(CalendarContract.Calendars.CONTENT_URI.toString())){List<Object[]>rows=new ArrayList<>();synchronized(calendars){for(Long id:calendars)rows.add(new Object[]{id});}Thread.yield();return new Rows(rows);}return new Rows(Collections.emptyList());}
 public Uri insert(Uri u,ContentValues v){long id=next.incrementAndGet();if(u.toString().startsWith(CalendarContract.Calendars.CONTENT_URI.toString()))calendars.add(id);else{ContentValues c=new ContentValues();c.putAll(v);events.put(id,c);}return Uri.parse(u.toString().split("[?]",2)[0]+"/"+id);}
 public int update(Uri u,ContentValues v,String s,String[]a){return 0;}
 public int delete(Uri u,String s,String[]a){if(u.toString().startsWith(CalendarContract.Calendars.CONTENT_URI.toString())){calendars.remove(Long.valueOf(u.getLastPathSegment()));return 1;}int count=0;for(Long id:new ArrayList<>(events.keySet()))if(String.valueOf(events.get(id).get(CalendarContract.Events.CALENDAR_ID)).equals(a[0])){events.remove(id);count++;}return count;}}
 @Test public void concurrentInitialSyncMustNotLeavePrivateCalendarAfterSignout()throws Exception{Provider provider=new Provider();NativeDataReprosTest.Ctx context=new NativeDataReprosTest.Ctx(){public ContentResolver getContentResolver(){return provider;}};JSONArray desired=new JSONArray().put(new JSONObject().put("key","block-A").put("title","Private account A appointment").put("start",1000).put("end",2000));ExecutorService workers=Executors.newFixedThreadPool(2);try{Future<?>a=workers.submit(()->{try{CalendarSync.sync(context,desired,0,3000);}catch(Exception e){throw new RuntimeException(e);}}),b=workers.submit(()->{try{CalendarSync.sync(context,desired,0,3000);}catch(Exception e){throw new RuntimeException(e);}});a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);int before=provider.calendars.size();CalendarSync.removeAll(context);System.out.println("calendars created="+before+" after successful removeAll="+provider.calendars.size()+" private events="+provider.events.size());assertTrue("sign-out must remove every app-owned calendar and private event",provider.calendars.isEmpty()&&provider.events.isEmpty());}finally{workers.shutdownNow();}}
 @Test public void removesEveryHistoricalDuplicateCalendar()throws Exception{
  Provider provider=new Provider();provider.calendars.add(1L);provider.calendars.add(2L);
  NativeDataReprosTest.Ctx context=new NativeDataReprosTest.Ctx(){public ContentResolver getContentResolver(){return provider;}};
  CalendarSync.removeAll(context);assertTrue(provider.calendars.isEmpty());
 }

}

